const THEMES = ['light', 'dark'];

const SELECTORS = {
  app: '.app', card: '.card', eyebrow: '.card-head .eyebrow', title: '.title', sub: '.sub',
  label1: '.field--earned .label', input1: '.field--earned .input', err1: '.field--earned .field-error',
  input2: '.field--total .input', err2: '.field--total .field-error',
  input3: '[class*="field--pass"] .input', suffix: '.suffix', err3: '[class*="field--pass"] .field-error',
  rule: '.rule', scoreLabel: '.result .eyebrow', resultBody: '.result-body', resultMsg: '.result-msg',
  btn: '.btn', hint: '.hint', kbd: 'kbd',
};
const PROPS = ['color', 'backgroundColor', 'fontSize', 'fontWeight', 'lineHeight', 'letterSpacing', 'borderTopColor',
  'borderTopWidth', 'borderRadius', 'boxShadow', 'paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft', 'marginTop', 'marginBottom', 'minHeight', 'fontFamily', 'fontVariantNumeric', 'textTransform'];

async function measure(page) {
  return page.evaluate(({ SELECTORS, PROPS }) => {
    const out = {};
    for (const [k, sel] of Object.entries(SELECTORS)) {
      const n = document.querySelector(sel);
      if (!n) { out[k] = null; continue; }
      const r = n.getBoundingClientRect();
      const cs = getComputedStyle(n);
      const o = { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) };
      for (const p of PROPS) o[p] = cs[p];
      out[k] = o;
    }
    out._scroll = { sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth };
    out._bodyBg = getComputedStyle(document.body).backgroundColor;
    out._inputValues = [...document.querySelectorAll('.input')].map((i) => i.value);
    out._texts = [...document.querySelectorAll('.card *')].filter((n) => n.children.length === 0 && n.textContent.trim()).map((n) => n.textContent);
    return out;
  }, { SELECTORS, PROPS });
}

async function isolateMock(page, theme) {
  await page.evaluate((theme) => {
    const frame = document.querySelector(`#desktop-idle .theme--${theme}.viewport`).cloneNode(true);
    frame.style.border = '0'; frame.style.borderRadius = '0'; frame.style.minHeight = '100vh';
    document.body.style.margin = '0';
    document.body.replaceChildren(frame);
  }, theme);
}

(async () => {
  const browser = await chromium.launch();
