      page.on('console', (m) => msgs.push(`${m.type()}: ${m.text()}`));
      page.on('pageerror', (e) => msgs.push(`pageerror: ${e.message}`));
      await page.goto(APP);
      await page.waitForSelector('.card');
      const key = `app-${w}-${theme}`;
      results[key] = await measure(page);
      results[key]._console = msgs;
      if (w !== 320) {
        await page.screenshot({ path: `${OUT}/s0rev-app-${w}-${theme}.png`, fullPage: true });
        // keyboard focus: Tab once lands on Marks earned
        await page.keyboard.press('Tab');
        results[key]._focus = await page.evaluate(() => {
          const a = document.activeElement; const cs = getComputedStyle(a);
          return { id: a.id, outline: `${cs.outlineWidth} ${cs.outlineStyle} ${cs.outlineColor}`, offset: cs.outlineOffset };
        });
        await page.screenshot({ path: `${OUT}/s0rev-app-${w}-${theme}-focus.png`, fullPage: true });
        // tab through to button and record ring
        await page.keyboard.press('Tab'); await page.keyboard.press('Tab'); await page.keyboard.press('Tab');
        results[key]._focusBtn = await page.evaluate(() => {
          const a = document.activeElement; const cs = getComputedStyle(a);
          return { tag: a.tagName, text: a.textContent, outline: `${cs.outlineWidth} ${cs.outlineStyle} ${cs.outlineColor}`, offset: cs.outlineOffset };
        });
        await page.screenshot({ path: `${OUT}/s0rev-app-${w}-${theme}-focusbtn.png`, fullPage: true });
      }
      await ctx.close();

      // mockup state (a)
      const mctx = await browser.newContext({ viewport: { width: w, height: 900 }, colorScheme: theme, deviceScaleFactor: 1 });
      const mpage = await mctx.newPage();
      await mpage.goto(MOCK);
      await isolateMock(mpage, theme);
      results[`mock-${w}-${theme}`] = await measure(mpage);
      if (w !== 320) await mpage.screenshot({ path: `${OUT}/s0rev-mock-${w}-${theme}.png`, fullPage: true });
      await mctx.close();
    }
  }
  await browser.close();
  require('fs').writeFileSync(`${OUT}/s0rev-measure.json`, JSON.stringify(results, null, 1));
  console.log('done');
})();

