// Style-only checks on the built shell: contrast, focus modality, reduced motion, reserved heights.
// Error/result markup is copied from mockup.html into the test browser's DOM only (no source edits).
const path = require('path');
const { execSync } = require('child_process');
const { chromium } = require(path.join(execSync('npm root -g').toString().trim(), 'playwright'));
const OUT = '/tmp/claude-0/-home-user/aea11bb9-83e3-5459-94fc-a24723a2132a/scratchpad';
const APP = 'http://127.0.0.1:4174/';
const MOCK = 'file:///home/user/Web-Calculator-fresh/sabee-khan-calculator/docs/process/design/mockup.html';

const lum = ([r, g, b]) => { const f = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; }; return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b); };
const ratio = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return ((x + 0.05) / (y + 0.05)).toFixed(2); };
const rgb = (s) => s.match(/\d+(\.\d+)?/g).slice(0, 3).map(Number);

(async () => {
  const browser = await chromium.launch();
  // grab mockup snippets: state (d) error field + result body, state (b) result body
  const mp = await (await browser.newContext()).newPage();
  await mp.goto(MOCK);
  const snip = await mp.evaluate(() => ({
    errField: document.querySelector('#desktop-error .theme--light .field--earned .field-error').innerHTML,
    errBody: document.querySelector('#desktop-error .theme--light .result-body').innerHTML,
    passBody: document.querySelector('#desktop-pass .theme--light .result-body').innerHTML,
    failBody: document.querySelector('#desktop-fail .theme--light .result-body').innerHTML,
    noPassBody: document.querySelector('#desktop-nopass .theme--light .result-body').innerHTML,
  }));
  for (const theme of ['light', 'dark']) {
    for (const w of [320, 375, 768, 1280]) {
      const ctx = await browser.newContext({ viewport: { width: w, height: 900 }, colorScheme: theme, reducedMotion: 'reduce' });
      const page = await ctx.newPage();
      await page.goto(APP); await page.waitForSelector('.card');
      const c = await page.evaluate(() => {
        const g = (sel, p) => getComputedStyle(document.querySelector(sel))[p];
        return {
          text: g('.title', 'color'), muted: g('.label', 'color'), surface: g('.card', 'backgroundColor'), bg: getComputedStyle(document.body).backgroundColor,
          accent: g('.btn', 'color'), fieldBorder: g('.input', 'borderTopColor'), hint: g('.hint', 'color'), resultMsg: g('.result-msg', 'color'), suffix: g('.suffix', 'color'),
          errSlotH: [...document.querySelectorAll('.field-error')].map((n) => n.getBoundingClientRect().height),
          resultH: document.querySelector('.result-body').getBoundingClientRect().height,
          transition: g('.input', 'transitionDuration') + ' / ' + g('.btn', 'transitionDuration'),
          inputH: document.querySelector('.input').getBoundingClientRect().height,
          btn: (() => { const r = document.querySelector('.btn').getBoundingClientRect(); return [r.width, r.height]; })(),
          inputW: document.querySelector('.input').getBoundingClientRect().width,
          tabular: g('.input', 'fontVariantNumeric'),
        };
      });
      const contrast = {
        'text/surface': ratio(rgb(c.text), rgb(c.surface)), 'muted/surface': ratio(rgb(c.muted), rgb(c.surface)), 'accent/surface': ratio(rgb(c.accent), rgb(c.surface)),
        'fieldBorder/surface': ratio(rgb(c.fieldBorder), rgb(c.surface)), 'hint/surface': ratio(rgb(c.hint), rgb(c.surface)), 'resultMsg/surface': ratio(rgb(c.resultMsg), rgb(c.surface)),
        'suffix/surface': ratio(rgb(c.suffix), rgb(c.surface)),
      };
      // Mouse click on input -> ring expected; mouse click on button -> no ring expected
      await page.mouse.click(...(await page.locator('#total').boundingBox().then((b) => [b.x + 10, b.y + 10])));
      const mouseInput = await page.evaluate(() => getComputedStyle(document.activeElement).outlineStyle + ' ' + document.activeElement.id);
      const bb = await page.locator('.btn').boundingBox();
      await page.mouse.click(bb.x + 5, bb.y + 5);
      const mouseBtn = await page.evaluate(() => getComputedStyle(document.activeElement).outlineStyle + ' ' + document.activeElement.tagName);
      await page.mouse.move(0, 0);
      // reserved heights: measure card + button across injected states
      const geo = () => page.evaluate(() => ({ card: document.querySelector('.card').getBoundingClientRect().height, btnY: document.querySelector('.btn').getBoundingClientRect().y, sw: document.documentElement.scrollWidth }));
      const states = { idle: await geo() };
      for (const [name, body] of [['pass', snip.passBody], ['fail', snip.failBody], ['nopass', snip.noPassBody], ['error', snip.errBody]]) {
        await page.evaluate(({ body, name, errField }) => {
          document.querySelector('.result-body').innerHTML = body;
          const e = document.querySelector('#earned-error'), i = document.querySelector('#earned');
          if (name === 'error') { e.innerHTML = errField; i.setAttribute('aria-invalid', 'true'); i.value = '23.5'; }
          else { e.innerHTML = ''; i.removeAttribute('aria-invalid'); }
        }, { body, name, errField: snip.errField });
        states[name] = await geo();
        if (name === 'error' && (w === 375 || w === 1280)) await page.screenshot({ path: `${OUT}/s0rev-inj-error-${w}-${theme}.png`, fullPage: true });
        if (name === 'pass' && (w === 375 || w === 1280)) await page.screenshot({ path: `${OUT}/s0rev-inj-pass-${w}-${theme}.png`, fullPage: true });
      }
      // longest field error (2 lines narrow) in the total slot
      await page.evaluate(() => { document.querySelector('#total-error').innerHTML = document.querySelector('#earned-error').innerHTML.replace(/>[^<]*<\/span>\s*$/, '>Total marks possible can\'t be more than 1,000,000.</span>'); });
